def set_verify(session, hostname, username):
    """Set the verify cookie for the active lab host."""
    session.cookies.set(
        "verify",
        username,
        domain=hostname,
        path="/",
    )
def extract_text(html):
    """Return readable page text and the parsed HTML."""
    soup = BeautifulSoup(html, "html.parser")
    for element in soup(["script", "style"]):
        element.decompose()
    return "\n".join(
        item.strip()
        for item in soup.stripped_strings
        if item.strip()
    ), soup

