import os, statistics, sys, time
THRESHOLD = 3.0
def build_profile(history, features):
return {f: {"mean": statistics.mean(r[f] for r in history),
"std":  statistics.pstdev(r[f] for r in history)} for f in features}
def z_score(value, mean, std):
if std == 0:
std = 0.1
return abs(value - mean) / std
def anomaly_score(login, profile, features):
scores = [z_score(login[f], profile[f]["mean"], profile[f]["std"]) for f in features]
return sum(scores) / len(scores)
def authenticate(login, profile, features, threshold):
score = anomaly_score(login, profile, features)
return ("BLOCK  (step-up MFA required)" if score > threshold else "ALLOW"), score
