import bcrypt
def register(password: str) -> bytes:
    salt = bcrypt.gensalt(rounds=12)
    return bcrypt.hashpw(password.encode(), salt)

def verify(password: str, stored_hash: bytes) -> 
bool:
    return bcrypt.checkpw(
        password.encode(), stored_hash
    )
# Never log, print, or transmit the raw password.
# Always compare using constant-time checkpw(),
# never a manual '==' string comparison.

